    omit: "城市题不详讲商场楼层和店铺；商场题不大段介绍外滩和高楼。",
    draftCues: ["Shanghai-GF", "three-day trip", "Bund-Lujiazui", "mall-dinner", "rain-two hours", "visit again"],
